package org.example.strategy_pattern.delivery;import org.example.strategy_pattern.delivery.impl.ExpressShippingStrategy;import org.example.strategy_pattern.delivery.impl.SameDayShippingStrategy;import org.example.strategy_pattern.delivery.impl.StandardShippingStrategy;import java.util.EnumMap;public class ShippingService {    private final EnumMap<EShippingType, ShippingStrategy> strategyMap = new EnumMap<>(EShippingType.class);    public ShippingService() {        strategyMap.put(EShippingType.STANDARD, new StandardShippingStrategy());        strategyMap.put(EShippingType.EXPRESS, new ExpressShippingStrategy());        strategyMap.put(EShippingType.SAME_DAY, new SameDayShippingStrategy());    }    public int getShippingFee(Order order, EShippingType type) {        ShippingStrategy strategy = strategyMap.getOrDefault(type, new StandardShippingStrategy());        return strategy.calculateFee(order);    }}